-- Zone Gore Overhaul, kid mode for particles: particles\set on the DX9 (R2) renderer.
-- Exactly the C++ particle blender (xray-monolith Blender_Particle.cpp, R2 branch) with this
-- mod list's shaders.xr settings for particles\set (from base:files.db0): priority 1, strict sorting off,
-- blending SET, texture clamp on. It only exists so that effects pointed at zgo\particle_*
-- load on this renderer (a missing shader name is fatal there); kid mode hides nothing here.
-- Generated by tools/zgo_kidfx/kidfx_pe.py shaders --write; tests/zgo_test_kidfx.lua checks it.

function normal(shader, t_base, t_second, t_detail)
	shader:begin("deffer_particle", "deffer_particle")
		:sorting(1, false)
		:fog(false)
		:zb(true, true)
		:blend(false, blend.one, blend.zero)
		:aref(false, 200)
	shader:sampler("s_base"):texture(t_base):clamp()
	shader:sampler("s_position"):texture("$user$position")
end

function l_point(shader, t_base, t_second, t_detail)
	shader:begin("particle", "particle")
		:sorting(1, false)
		:fog(false)
		:zb(true, true)
		:blend(false, blend.one, blend.zero)
		:aref(true, 200)
	shader:sampler("s_base"):texture(t_base):clamp()
	shader:sampler("s_position"):texture("$user$position")
end
